insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('class6-history-ancient-india', 'Ancient India', 'History', 'class', 'Class 6', '', 'From the Stone Age to the Gupta Empire.', 0) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-1', 3, 'class6-history-ancient-india', 'The Stone Age in India', 'Ancient India', 'History', 0, 'Let’s go back to the very beginning, when people made their tools from stone.', '["The Stone Age is the long period when people made their tools from stone.","It is divided into the Old (Palaeolithic), Middle (Mesolithic) and New (Neolithic) Stone Age.","Early people were hunter-gatherers who moved from place to place in search of food.","The rock shelters of Bhimbetka in Madhya Pradesh have paintings made thousands of years ago.","In the New Stone Age, people began farming, keeping animals and living in villages.","Mehrgarh, in present-day Pakistan, is one of the earliest farming villages in South Asia."]'::jsonb, 'The Bhimbetka rock shelters are a UNESCO World Heritage Site.', '[{"heading":"Life with stone tools","text":"For hundreds of thousands of years, people in India lived by hunting animals, fishing and gathering fruits, roots and seeds. They made tools by chipping stones into sharp edges, and moved from place to place following food, water and the seasons."},{"heading":"Three stages","text":"Historians divide the Stone Age into three stages. The Old Stone Age (Palaeolithic) was the longest. In the Middle Stone Age (Mesolithic), tools became small and sharp, called microliths. In the New Stone Age (Neolithic), people began farming, herding animals and making polished stone tools."},{"heading":"Paintings and first villages","text":"At Bhimbetka in Madhya Pradesh, rock shelters have paintings of animals, hunting and dancing made thousands of years ago. Once people started growing crops such as wheat and barley, they settled in villages. Mehrgarh, in present-day Pakistan, is one of the earliest such farming villages in South Asia."}]'::jsonb, '[{"topic":"History","question":"Where are India’s famous Stone Age rock shelters?","options":["Bhimbetka","Ajanta","Sanchi","Hampi"],"correct_index":0,"explanation":"The Bhimbetka rock shelters in Madhya Pradesh have very old cave paintings."},{"topic":"History","question":"In which age did people start farming?","options":["Old Stone Age","Middle Stone Age","New Stone Age","None"],"correct_index":2,"explanation":"Farming began in the New Stone Age, also called the Neolithic Age."},{"topic":"History","question":"Mehrgarh is known as one of the earliest…","options":["Ports","Farming villages","Temples","Forts"],"correct_index":1,"explanation":"Mehrgarh is one of the earliest farming villages in South Asia."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-2', 3, 'class6-history-ancient-india', 'The Indus Valley Civilisation', 'Ancient India', 'History', 1, 'Think of it as India’s earliest city planners. Let’s see what they built.', '["One of the world’s earliest urban civilisations, about 4,500 years ago.","Famous sites include Harappa, Mohenjo-daro, Dholavira and Lothal.","Cities were planned, with grid-like streets and covered drains.","Mohenjo-daro had the Great Bath, a large public water tank.","Lothal in Gujarat had a dockyard, which shows they traded by sea.","Their writing, the Indus script, has still not been deciphered."]'::jsonb, 'Harappa gave this civilisation its other name, the Harappan civilisation.', '[{"heading":"Cities by the rivers","text":"Around 4,500 years ago, large planned cities grew up along the Indus river and its neighbours, in parts of today’s Pakistan and north-west India. Harappa was the first of these cities to be found, in the 1920s, so this is also called the Harappan civilisation."},{"heading":"Well-planned towns","text":"Streets crossed each other at right angles, like a grid. Houses were built with baked bricks of a standard size, and covered drains carried away dirty water. Mohenjo-daro had the Great Bath, a large brick tank that may have been used for special ceremonies."},{"heading":"Work and trade","text":"People farmed, kept animals, made beads, pottery, seals and metal objects. Lothal in Gujarat had a dockyard, and Harappan goods have been found as far away as Mesopotamia. Their script is seen on many seals, but nobody has been able to read it yet."}]'::jsonb, '[{"topic":"History","question":"Where was the Great Bath found?","options":["Harappa","Mohenjo-daro","Lothal","Kalibangan"],"correct_index":1,"explanation":"The Great Bath, a large public water tank, was found at Mohenjo-daro."},{"topic":"History","question":"Which Indus Valley site had a dockyard?","options":["Harappa","Rakhigarhi","Lothal","Dholavira"],"correct_index":2,"explanation":"Lothal in Gujarat had a dockyard, a sign of trade by sea."},{"topic":"History","question":"Why is it also called the Harappan civilisation?","options":["Harappa was its capital","Harappa was the first site found","Harappa was its largest port","A king named Harappa ruled it"],"correct_index":1,"explanation":"Harappa was the first site to be discovered, so the civilisation is named after it."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-3', 3, 'class6-history-ancient-india', 'The Vedic Age', 'Ancient India', 'History', 2, 'This age is named after some of the oldest books in the world. Let’s open them!', '["The Vedic Age is named after the Vedas, the oldest sacred texts of India.","There are four Vedas: the Rigveda, Samaveda, Yajurveda and Atharvaveda.","The Rigveda is the oldest of the four.","The Vedas were composed in Sanskrit and passed on by word of mouth for centuries.","Early Vedic people were mainly cattle herders; later they settled down as farmers."]'::jsonb, 'The Gayatri Mantra comes from the Rigveda.', '[{"heading":"The Vedas","text":"The Vedas are the oldest sacred texts of India, composed in Sanskrit. There are four: the Rigveda, Samaveda, Yajurveda and Atharvaveda. The Rigveda, a collection of hymns to gods such as Agni, Indra and Soma, is the oldest."},{"heading":"Remembered by heart","text":"For many centuries the Vedas were not written down. Students learned them by listening to teachers and repeating every word with great care, so they were passed on by word of mouth."},{"heading":"How people lived","text":"Early Vedic people kept cattle, horses, sheep and goats, and cattle were a measure of wealth. Over time they settled down and became farmers. Later, society came to be divided into four groups called varnas."}]'::jsonb, '[{"topic":"History","question":"Which is the oldest of the four Vedas?","options":["Samaveda","Rigveda","Yajurveda","Atharvaveda"],"correct_index":1,"explanation":"The Rigveda is the oldest of the four Vedas."},{"topic":"History","question":"How many Vedas are there?","options":["Two","Three","Four","Six"],"correct_index":2,"explanation":"There are four Vedas: Rigveda, Samaveda, Yajurveda and Atharvaveda."},{"topic":"History","question":"In which language were the Vedas composed?","options":["Pali","Prakrit","Sanskrit","Tamil"],"correct_index":2,"explanation":"The Vedas were composed in Sanskrit."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-4', 3, 'class6-history-ancient-india', 'Buddhism and Jainism', 'Ancient India', 'History', 3, 'Two great teachers showed people a peaceful way to live. Let’s meet them.', '["Gautama Buddha founded Buddhism. He was born at Lumbini, in present-day Nepal.","He gained enlightenment under a Bodhi tree at Bodh Gaya, in Bihar.","He gave his first sermon at Sarnath, near Varanasi.","Vardhamana Mahavira was the 24th and last tirthankara of Jainism.","Both taught ahimsa, which means non-violence."]'::jsonb, 'The Buddha taught the Middle Path, a life without extremes.', '[{"heading":"The Buddha","text":"Siddhartha Gautama was born at Lumbini, in present-day Nepal. He left his comfortable life to understand why people suffer. After long meditation under a Bodhi tree at Bodh Gaya, he gained enlightenment and became the Buddha, “the awakened one”."},{"heading":"His teaching","text":"The Buddha gave his first sermon at Sarnath, near Varanasi. He taught kindness to all living beings and the Middle Path, a life that avoids extremes. He taught in Prakrit, the language of ordinary people, so everyone could understand."},{"heading":"Mahavira and Jainism","text":"Vardhamana Mahavira was the 24th and last tirthankara, or great teacher, of Jainism. He taught that people should not harm any living being. This idea, ahimsa or non-violence, is central to both Jainism and Buddhism."}]'::jsonb, '[{"topic":"History","question":"Where did the Buddha give his first sermon?","options":["Bodh Gaya","Lumbini","Sarnath","Kushinagar"],"correct_index":2,"explanation":"The Buddha gave his first sermon at Sarnath."},{"topic":"History","question":"Mahavira was which tirthankara of Jainism?","options":["1st","12th","23rd","24th"],"correct_index":3,"explanation":"Vardhamana Mahavira was the 24th and last tirthankara."},{"topic":"History","question":"Where did the Buddha gain enlightenment?","options":["Sarnath","Bodh Gaya","Rajgir","Vaishali"],"correct_index":1,"explanation":"He gained enlightenment under a Bodhi tree at Bodh Gaya."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-5', 3, 'class6-history-ancient-india', 'The Mauryan Empire', 'Ancient India', 'History', 4, 'Here comes one of India’s first big empires, and a king who chose peace.', '["Chandragupta Maurya founded the Mauryan Empire around 321 BCE.","His adviser Chanakya, also called Kautilya, is linked with the Arthashastra, a book on running a state.","The capital was Pataliputra, near today’s Patna.","Ashoka, Chandragupta’s grandson, fought the Kalinga War and then turned to Buddhism.","Ashoka’s messages, called edicts, were carved on rocks and pillars across the empire."]'::jsonb, 'The Lion Capital of Ashoka at Sarnath is India’s National Emblem.', '[{"heading":"A big empire","text":"Chandragupta Maurya founded the Mauryan Empire around 321 BCE, with the help of his adviser Chanakya, also called Kautilya. Its capital was Pataliputra, near today’s Patna. The empire grew to cover most of the Indian subcontinent."},{"heading":"Ashoka changes his mind","text":"Ashoka, Chandragupta’s grandson, fought a terrible war to win Kalinga, in today’s Odisha. Seeing so much death and suffering, he decided never to fight wars of conquest again and turned to the Buddha’s teachings."},{"heading":"Messages on stone","text":"Ashoka had his messages, called edicts, carved on rocks and tall pillars across his empire. They asked people to be kind, respect elders and all religions, and treat animals well. The Lion Capital of his pillar at Sarnath is now India’s National Emblem."}]'::jsonb, '[{"topic":"History","question":"What was the capital of the Mauryan Empire?","options":["Ujjain","Taxila","Pataliputra","Kannauj"],"correct_index":2,"explanation":"The Mauryan capital was Pataliputra, near today’s Patna."},{"topic":"History","question":"After which war did Ashoka turn to Buddhism?","options":["Kalinga War","Battle of Panipat","Kurukshetra War","Battle of Hydaspes"],"correct_index":0,"explanation":"The suffering of the Kalinga War led Ashoka to turn to Buddhism."},{"topic":"History","question":"The Arthashastra is linked with…","options":["Ashoka","Kautilya","Kalidasa","Megasthenes"],"correct_index":1,"explanation":"The Arthashastra is linked with Kautilya, also called Chanakya."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('ancient-india-6', 3, 'class6-history-ancient-india', 'The Gupta Empire', 'Ancient India', 'History', 5, 'Welcome to a time of great art, poetry and science. Some call it a golden age!', '["The Gupta Empire became powerful under Chandragupta I, from about 320 CE.","This period is often called the “Golden Age” of ancient India.","Samudragupta was a great conqueror. His coins show him playing the veena.","Aryabhata, the famous mathematician and astronomer, lived in this period.","The poet Kalidasa wrote the play Abhijnanashakuntalam."]'::jsonb, 'The Chinese traveller Faxian (Fa-Hien) visited India during the Gupta period.', '[{"heading":"The Gupta kings","text":"The Gupta Empire grew powerful under Chandragupta I, from about 320 CE. His son Samudragupta won many battles and was also a musician: his coins show him playing the veena. Chandragupta II later ruled a large and wealthy kingdom."},{"heading":"A golden age","text":"This period is often called the Golden Age of ancient India because of its great works in art, literature and science. The poet Kalidasa wrote plays such as Abhijnanashakuntalam, and Aryabhata wrote on mathematics and astronomy."},{"heading":"A visitor from China","text":"The Chinese Buddhist traveller Faxian (Fa-Hien) visited India during the Gupta period to collect Buddhist texts, and wrote about what he saw on his journey."}]'::jsonb, '[{"topic":"History","question":"The Gupta period is often called the…","options":["Iron Age","Golden Age","Dark Age","Stone Age"],"correct_index":1,"explanation":"The Gupta period is often called the Golden Age of ancient India."},{"topic":"History","question":"Which famous astronomer lived in the Gupta period?","options":["Aryabhata","Bhaskara II","C. V. Raman","Ramanujan"],"correct_index":0,"explanation":"Aryabhata, a mathematician and astronomer, lived in the Gupta period."},{"topic":"History","question":"Who wrote Abhijnanashakuntalam?","options":["Banabhatta","Kalidasa","Tulsidas","Kautilya"],"correct_index":1,"explanation":"The poet Kalidasa wrote Abhijnanashakuntalam."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.courses (id, title, subject, section, student_class, collection, description, sort) values ('gk-polity', 'Indian Polity', 'Politics', 'explore', '', 'General Knowledge', 'The Constitution, our rights and duties, and how India is governed.', 1) on conflict (id) do update set title = excluded.title, subject = excluded.subject, section = excluded.section, student_class = excluded.student_class, collection = excluded.collection, description = excluded.description, sort = excluded.sort;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-1', 3, 'gk-polity', 'Making of the Constitution', 'The Constitution', 'Politics', 0, 'How do you write the rulebook for a whole country? Let’s see how India did it.', '["The Constitution was written by the Constituent Assembly, which first met on 9 December 1946.","Members of the Assembly were elected indirectly, by the members of the provincial legislative assemblies.","Dr Rajendra Prasad was elected President of the Constituent Assembly.","Dr B. R. Ambedkar chaired the Drafting Committee, set up in August 1947.","The work took about 2 years, 11 months and 18 days.","The Constitution was adopted on 26 November 1949 and came into force on 26 January 1950."]'::jsonb, 'B. N. Rau was the Constitutional Adviser to the Constituent Assembly.', '[{"heading":"Why a constitution?","text":"A constitution is the basic law of a country. It sets out how the government is formed, what powers each part has, and what rights citizens enjoy. Every other law must follow it."},{"heading":"The Constituent Assembly","text":"The Constituent Assembly first met on 9 December 1946. Dr Rajendra Prasad was elected its President. Its members were chosen by the provincial legislative assemblies, and they debated every part of the draft openly."},{"heading":"From draft to law","text":"The Drafting Committee, chaired by Dr B. R. Ambedkar, prepared the text. The Assembly adopted the Constitution on 26 November 1949, now marked as Constitution Day. It came into force on 26 January 1950, which we celebrate as Republic Day."}]'::jsonb, '[{"topic":"Politics","question":"Who chaired the Drafting Committee of the Constitution?","options":["Jawaharlal Nehru","Dr B. R. Ambedkar","Dr Rajendra Prasad","Sardar Patel"],"correct_index":1,"explanation":"Dr B. R. Ambedkar chaired the Drafting Committee of the Constitution."},{"topic":"Politics","question":"When did the Constituent Assembly adopt the Constitution?","options":["15 August 1947","26 November 1949","26 January 1950","9 December 1946"],"correct_index":1,"explanation":"It was adopted on 26 November 1949 and came into force on 26 January 1950."},{"topic":"Politics","question":"Who was the President of the Constituent Assembly?","options":["Dr Rajendra Prasad","Dr B. R. Ambedkar","B. N. Rau","Jawaharlal Nehru"],"correct_index":0,"explanation":"Dr Rajendra Prasad was elected President of the Constituent Assembly."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-2', 3, 'gk-polity', 'Sources and features', 'The Constitution', 'Politics', 1, 'Our Constitution borrowed good ideas from around the world. Let’s find out which ones!', '["India has the longest written constitution of any country in the world.","When adopted it had 395 Articles, 22 Parts and 8 Schedules; today it has 12 Schedules.","The parliamentary system came from Britain, and Fundamental Rights were inspired by the USA.","The Directive Principles came from Ireland, and the Concurrent List from Australia.","A federation with a strong centre was inspired by Canada.","India has a single citizenship for the whole country."]'::jsonb, 'The Government of India Act, 1935 was the largest single source of the Constitution.', '[{"heading":"A long, written document","text":"Unlike Britain, whose constitution is mostly unwritten, India wrote everything down in one long document. When adopted it had 395 Articles in 22 Parts, and 8 Schedules. Amendments have added more, and there are now 12 Schedules."},{"heading":"Borrowed features","text":"The makers studied many constitutions. The parliamentary system came from Britain, the idea of Fundamental Rights from the USA, the Directive Principles from Ireland, the Concurrent List from Australia, and a federation with a strong centre from Canada. Much of the structure came from the Government of India Act, 1935."},{"heading":"Key features","text":"India is a federation with a strong centre: power is shared between the Union and the states. Citizens have a single citizenship, courts are independent, and every adult can vote."}]'::jsonb, '[{"topic":"Politics","question":"The Directive Principles were borrowed from which country?","options":["USA","Britain","Ireland","Canada"],"correct_index":2,"explanation":"The idea of Directive Principles came from Ireland."},{"topic":"Politics","question":"The idea of Fundamental Rights was inspired by…","options":["the USA","Australia","Ireland","Japan"],"correct_index":0,"explanation":"Fundamental Rights were inspired by the Bill of Rights of the USA."},{"topic":"Politics","question":"How many Schedules did the Constitution have when adopted?","options":["8","10","12","22"],"correct_index":0,"explanation":"It had 8 Schedules when adopted; there are 12 today."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-3', 3, 'gk-polity', 'The Preamble', 'The Constitution', 'Politics', 2, 'The Preamble is the Constitution’s opening promise. Let’s read it together!', '["The Preamble is the introduction to the Constitution and states its ideals.","It begins with “We, the people of India”: power comes from the people.","It calls India a Sovereign, Socialist, Secular, Democratic Republic.","It promises Justice, Liberty, Equality and Fraternity.","It is based on the Objectives Resolution moved by Jawaharlal Nehru on 13 December 1946.","In the Kesavananda Bharati case (1973), the Supreme Court held that the Preamble is part of the Constitution."]'::jsonb, 'The Preamble has been amended only once, by the 42nd Amendment in 1976, which added “Socialist”, “Secular” and “Integrity”.', '[{"heading":"We, the people","text":"The Preamble opens with “We, the people of India”. This shows that the Constitution gets its authority from the people. It grew out of the Objectives Resolution that Jawaharlal Nehru moved in the Constituent Assembly in December 1946."},{"heading":"What India is","text":"It describes India as Sovereign (free to decide for itself), Socialist, Secular (no official religion), Democratic (rule by elected representatives) and a Republic (the head of state is elected, not a king or queen)."},{"heading":"What it promises","text":"It promises citizens Justice (social, economic and political), Liberty (of thought, expression, belief, faith and worship), Equality (of status and opportunity) and Fraternity (the dignity of each person and the unity and integrity of the nation)."}]'::jsonb, '[{"topic":"Politics","question":"Which amendment added “Socialist” and “Secular” to the Preamble?","options":["1st","24th","42nd","44th"],"correct_index":2,"explanation":"The 42nd Amendment (1976) added “Socialist”, “Secular” and “Integrity”."},{"topic":"Politics","question":"Who moved the Objectives Resolution?","options":["Dr B. R. Ambedkar","Jawaharlal Nehru","Dr Rajendra Prasad","Mahatma Gandhi"],"correct_index":1,"explanation":"Jawaharlal Nehru moved the Objectives Resolution in December 1946."},{"topic":"Politics","question":"In which case did the Supreme Court say the Preamble is part of the Constitution?","options":["Kesavananda Bharati","Berubari Union","Golaknath","Minerva Mills"],"correct_index":0,"explanation":"In Kesavananda Bharati (1973), the Court held the Preamble is part of the Constitution."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-4', 3, 'gk-polity', 'Fundamental Rights', 'Rights and Duties', 'Politics', 3, 'These are the rights every Indian citizen can go to court to protect. Let’s learn all six!', '["Fundamental Rights are in Part III of the Constitution, Articles 12 to 35.","There are six: Equality, Freedom, Against Exploitation, Freedom of Religion, Cultural and Educational, and Constitutional Remedies.","The Right to Property was removed from this list by the 44th Amendment (1978); it is now a legal right under Article 300A.","Article 21A, the right to education for children aged 6 to 14, was added by the 86th Amendment (2002).","Dr Ambedkar called Article 32, the right to go to the Supreme Court, the “heart and soul” of the Constitution.","Courts protect these rights with five writs, such as habeas corpus and mandamus."]'::jsonb, 'Article 17 abolishes untouchability.', '[{"heading":"Six rights","text":"Part III lists six groups of rights: the Right to Equality (Articles 14 to 18), the Right to Freedom (19 to 22), the Right against Exploitation (23 and 24), the Right to Freedom of Religion (25 to 28), Cultural and Educational Rights (29 and 30), and the Right to Constitutional Remedies (32)."},{"heading":"Changes over time","text":"The Right to Property was once a Fundamental Right. The 44th Amendment in 1978 removed it from Part III; it is now a legal right under Article 300A. The 86th Amendment in 2002 added Article 21A: free and compulsory education for children aged 6 to 14."},{"heading":"Going to court","text":"If a Fundamental Right is taken away, a person can go straight to the Supreme Court under Article 32. Courts can issue five kinds of orders, called writs: habeas corpus, mandamus, prohibition, certiorari and quo warranto."}]'::jsonb, '[{"topic":"Politics","question":"Which Article did Dr Ambedkar call the “heart and soul” of the Constitution?","options":["Article 14","Article 19","Article 21","Article 32"],"correct_index":3,"explanation":"Article 32, the right to constitutional remedies, was called its “heart and soul”."},{"topic":"Politics","question":"The Right to Property is now a legal right under which Article?","options":["Article 31","Article 300A","Article 19","Article 51A"],"correct_index":1,"explanation":"Since the 44th Amendment (1978), it is a legal right under Article 300A."},{"topic":"Politics","question":"How many groups of Fundamental Rights are there today?","options":["Five","Six","Seven","Eleven"],"correct_index":1,"explanation":"There are six; there were seven before the Right to Property was removed."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-5', 3, 'gk-polity', 'Directive Principles and Fundamental Duties', 'Rights and Duties', 'Politics', 4, 'Rights come with goals for the government, and duties for us. Let’s look at both.', '["The Directive Principles of State Policy are in Part IV, Articles 36 to 51.","They are goals for the government; courts cannot enforce them, but they are fundamental in governing the country (Article 37).","Examples: equal pay for equal work, village panchayats (Article 40) and a uniform civil code (Article 44).","Fundamental Duties are in Article 51A, added by the 42nd Amendment (1976) on the Swaran Singh Committee’s advice.","There were 10 duties at first; the 11th, about educating children aged 6 to 14, was added in 2002."]'::jsonb, 'The idea of Directive Principles was borrowed from the Irish Constitution.', '[{"heading":"Goals for the government","text":"The Directive Principles (Part IV) tell the government what kind of society to work towards: fair wages, equal pay for equal work, health, education, village panchayats and protecting the environment. A citizen cannot go to court to enforce them, but governments must keep them in mind when making laws."},{"heading":"Some examples","text":"Article 40 asks the state to organise village panchayats, Article 44 to work towards a uniform civil code, Article 48A to protect the environment and wildlife, Article 50 to keep the judiciary separate from the executive, and Article 51 to promote international peace."},{"heading":"Our duties","text":"Fundamental Duties were added in 1976 as Article 51A, on the recommendation of the Swaran Singh Committee. They include respecting the Constitution, the national flag and anthem, protecting the environment and developing a scientific temper. An eleventh duty, for parents to give children aged 6 to 14 a chance to study, was added in 2002."}]'::jsonb, '[{"topic":"Politics","question":"Fundamental Duties were added on the advice of which committee?","options":["Sarkaria Commission","Swaran Singh Committee","Balwant Rai Mehta Committee","Kothari Commission"],"correct_index":1,"explanation":"The Swaran Singh Committee recommended adding Fundamental Duties in 1976."},{"topic":"Politics","question":"In which Article are the Fundamental Duties listed?","options":["Article 32","Article 44","Article 51A","Article 21A"],"correct_index":2,"explanation":"The Fundamental Duties are listed in Article 51A."},{"topic":"Politics","question":"Which Article asks the state to work towards a uniform civil code?","options":["Article 40","Article 44","Article 48A","Article 50"],"correct_index":1,"explanation":"Article 44 is the Directive Principle about a uniform civil code."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-6', 3, 'gk-polity', 'The President', 'Union Government', 'Politics', 5, 'The President is the head of our country. Let’s see how one is chosen and what they do.', '["The President is the head of state; the executive power of the Union is vested in the President (Article 53).","The President is elected by an electoral college of the elected members of both Houses of Parliament and of the state Legislative Assemblies.","The term is five years, and a President can be re-elected.","A candidate must be at least 35 years old.","A President can be removed only by impeachment, for violating the Constitution (Article 61).","Dr Rajendra Prasad was the first President, and the only one elected twice."]'::jsonb, 'The President takes the oath of office before the Chief Justice of India.', '[{"heading":"Head of state","text":"The President is the head of the Indian state and the supreme commander of the armed forces. Laws are made and government work is done in the President’s name, but in practice the President acts on the advice of the Council of Ministers."},{"heading":"How a President is chosen","text":"The people do not vote directly. An electoral college made up of the elected members of both Houses of Parliament and of the state Legislative Assemblies (including Delhi and Puducherry) elects the President for five years. A candidate must be at least 35 years old."},{"heading":"Special powers","text":"The President can declare a national emergency (Article 352), President’s rule in a state (Article 356) and a financial emergency (Article 360). The President can also grant pardons. Removal is only through impeachment by Parliament."}]'::jsonb, '[{"topic":"Politics","question":"What is the minimum age to become President of India?","options":["25 years","30 years","35 years","40 years"],"correct_index":2,"explanation":"A candidate for President must be at least 35."},{"topic":"Politics","question":"Which Article deals with impeaching the President?","options":["Article 52","Article 61","Article 72","Article 352"],"correct_index":1,"explanation":"Article 61 sets out how a President is impeached."},{"topic":"Politics","question":"Who was the first President of India?","options":["Dr S. Radhakrishnan","Dr Rajendra Prasad","Dr Zakir Husain","V. V. Giri"],"correct_index":1,"explanation":"Dr Rajendra Prasad was the first President, elected twice."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-7', 3, 'gk-polity', 'Prime Minister and Council of Ministers', 'Union Government', 'Politics', 6, 'The President is head of state, but who actually runs the government? Let’s find out.', '["The real executive power lies with the Prime Minister and the Council of Ministers.","The Council of Ministers aids and advises the President (Article 74).","The President appoints the Prime Minister, usually the leader of the majority in the Lok Sabha (Article 75).","The Council of Ministers is collectively responsible to the Lok Sabha.","Since the 91st Amendment (2003), the Council can have at most 15% of the Lok Sabha’s strength.","A minister who is not an MP must become one within six months."]'::jsonb, 'Jawaharlal Nehru was India’s first Prime Minister, from 1947 to 1964.', '[{"heading":"Who really governs","text":"India has a parliamentary system. The President is the formal head, but the Prime Minister and the Council of Ministers take the real decisions. Under Article 74, they aid and advise the President."},{"heading":"Choosing the Prime Minister","text":"After a general election, the President invites the leader of the party or alliance with a majority in the Lok Sabha to become Prime Minister. Other ministers are appointed on the Prime Minister’s advice."},{"heading":"Responsible to the Lok Sabha","text":"The Council of Ministers is collectively responsible to the Lok Sabha: if the Lok Sabha passes a vote of no confidence, the whole government must resign. Since 2003, the Council can have at most 15% as many members as the Lok Sabha."}]'::jsonb, '[{"topic":"Politics","question":"The Council of Ministers is collectively responsible to…","options":["the President","the Rajya Sabha","the Lok Sabha","the Supreme Court"],"correct_index":2,"explanation":"Under Article 75, it is collectively responsible to the Lok Sabha."},{"topic":"Politics","question":"The Council of Ministers can be at most what share of the Lok Sabha?","options":["10%","15%","20%","25%"],"correct_index":1,"explanation":"The 91st Amendment (2003) set the limit at 15%."},{"topic":"Politics","question":"A minister who is not an MP must become one within…","options":["three months","six months","one year","two years"],"correct_index":1,"explanation":"They must become a Member of Parliament within six months."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-8', 3, 'gk-polity', 'Parliament', 'Union Government', 'Politics', 7, 'Parliament makes the country’s laws. Let’s visit both its Houses!', '["Parliament is made up of the President, the Rajya Sabha and the Lok Sabha (Article 79).","The Lok Sabha has 543 elected seats and a five-year term, unless it is dissolved earlier.","The Rajya Sabha is a permanent House: it is never dissolved, and one-third of its members retire every two years.","The Rajya Sabha can have at most 250 members: 238 elected and 12 nominated by the President.","A Money Bill can be introduced only in the Lok Sabha.","The Speaker presides over the Lok Sabha; the Vice-President chairs the Rajya Sabha."]'::jsonb, 'The minimum age is 25 to be a Lok Sabha member and 30 for the Rajya Sabha.', '[{"heading":"Two Houses","text":"The Lok Sabha, or House of the People, is directly elected by the people and has 543 elected seats. The Rajya Sabha, or Council of States, is mostly elected by the state Legislative Assemblies, and 12 members are nominated by the President for their work in fields like art, science and social service."},{"heading":"How long they last","text":"The Lok Sabha’s term is five years, but it can be dissolved earlier. The Rajya Sabha is never dissolved: its members serve six years, and one-third of them retire every two years."},{"heading":"Making laws","text":"A bill becomes law after both Houses pass it and the President agrees. A Money Bill can only start in the Lok Sabha, and the Rajya Sabha can hold it back for at most 14 days. If the Houses disagree on an ordinary bill, the President can call a joint sitting, presided over by the Speaker."}]'::jsonb, '[{"topic":"Politics","question":"What is the minimum age to become a Rajya Sabha member?","options":["21 years","25 years","30 years","35 years"],"correct_index":2,"explanation":"It is 30 for the Rajya Sabha and 25 for the Lok Sabha."},{"topic":"Politics","question":"A Money Bill can be introduced only in…","options":["the Rajya Sabha","the Lok Sabha","either House","a joint sitting"],"correct_index":1,"explanation":"A Money Bill can be introduced only in the Lok Sabha."},{"topic":"Politics","question":"Who chairs the Rajya Sabha?","options":["The Speaker","The Prime Minister","The Vice-President","The President"],"correct_index":2,"explanation":"The Vice-President is the ex officio Chairman of the Rajya Sabha."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-9', 3, 'gk-polity', 'The Judiciary', 'Courts', 'Politics', 8, 'Courts protect the Constitution and our rights. Let’s climb up to the Supreme Court!', '["India has a single, integrated system of courts, with the Supreme Court at the top, then High Courts, then lower courts.","The Supreme Court began work on 28 January 1950 (Article 124).","Supreme Court judges retire at 65; High Court judges at 62.","A judge can be removed only by Parliament, through a special procedure, for proved misbehaviour or incapacity.","The Supreme Court issues writs under Article 32, and High Courts under Article 226.","Courts can strike down laws that go against the Constitution; this is called judicial review."]'::jsonb, 'Under Article 141, the Supreme Court’s decisions are binding on all courts in India.', '[{"heading":"One system of courts","text":"Unlike some federations, India has one connected system of courts. The Supreme Court in New Delhi is at the top. Each state (or group of states) has a High Court, and below them are district and other lower courts."},{"heading":"Independent judges","text":"To keep them independent, judges cannot be removed easily: only Parliament can remove them, by a special majority, for proved misbehaviour or incapacity. Supreme Court judges serve until 65, and High Court judges until 62."},{"heading":"Guarding the Constitution","text":"Courts can declare a law invalid if it goes against the Constitution; this power is called judicial review. Through writs under Articles 32 and 226, and through public interest litigation, they protect people’s rights."}]'::jsonb, '[{"topic":"Politics","question":"At what age do Supreme Court judges retire?","options":["60","62","65","70"],"correct_index":2,"explanation":"Supreme Court judges retire at 65; High Court judges at 62."},{"topic":"Politics","question":"Under which Article do High Courts issue writs?","options":["Article 32","Article 124","Article 141","Article 226"],"correct_index":3,"explanation":"High Courts issue writs under Article 226."},{"topic":"Politics","question":"The power of courts to strike down unconstitutional laws is called…","options":["judicial review","impeachment","quo warranto","a joint sitting"],"correct_index":0,"explanation":"Judicial review lets courts declare such laws invalid."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
insert into public.lessons (id, questions, course_id, title, unit, subject, sort, boojho_intro, key_points, remember, sections, quiz) values ('gk-polity-10', 3, 'gk-polity', 'Panchayati Raj and municipalities', 'Local Government', 'Politics', 9, 'Democracy starts in your own village or town. Let’s see how local government works!', '["The 73rd Amendment (1992) gave Panchayati Raj a place in the Constitution, in Part IX.","It came into force on 24 April 1993, now marked as National Panchayati Raj Day.","There are three levels: gram panchayat (village), panchayat samiti (block) and zila parishad (district).","At least one-third of the seats are reserved for women.","Panchayat elections are held every five years by the State Election Commission.","The 74th Amendment (1992) did the same for towns and cities, in Part IXA."]'::jsonb, 'Panchayati Raj was first launched at Nagaur in Rajasthan on 2 October 1959.', '[{"heading":"Where it began","text":"In 1957, the Balwant Rai Mehta Committee recommended a three-level system of local self-government. Rajasthan was the first state to start it, at Nagaur on 2 October 1959."},{"heading":"Part of the Constitution","text":"The 73rd Amendment of 1992 made panchayats part of the Constitution (Part IX), from 24 April 1993. It set up three levels, elections every five years, a State Election Commission, and reserved at least one-third of seats for women. The Eleventh Schedule lists 29 subjects panchayats can look after."},{"heading":"Towns and cities","text":"The 74th Amendment of 1992 did the same for urban areas, adding Part IXA on municipalities: nagar panchayats, municipal councils and municipal corporations. The Twelfth Schedule lists 18 subjects they handle."}]'::jsonb, '[{"topic":"Politics","question":"Which amendment gave Panchayati Raj a place in the Constitution?","options":["42nd","61st","73rd","86th"],"correct_index":2,"explanation":"The 73rd Amendment (1992) added Part IX on panchayats."},{"topic":"Politics","question":"Where was Panchayati Raj first launched in 1959?","options":["Nagaur, Rajasthan","Anand, Gujarat","Patna, Bihar","Pune, Maharashtra"],"correct_index":0,"explanation":"It began at Nagaur in Rajasthan on 2 October 1959."},{"topic":"Politics","question":"What share of panchayat seats is reserved for women?","options":["At least one-quarter","At least one-third","At least half","None"],"correct_index":1,"explanation":"At least one-third of the seats are reserved for women."}]'::jsonb) on conflict (id) do update set questions = excluded.questions, course_id = excluded.course_id, title = excluded.title, unit = excluded.unit, subject = excluded.subject, sort = excluded.sort, boojho_intro = excluded.boojho_intro, key_points = excluded.key_points, remember = excluded.remember, sections = excluded.sections, quiz = excluded.quiz;
